import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"27、【颐】 震下艮上","description":"周易尚氏学 - 27、【颐】 震下艮上","frontmatter":{"title":"27、【颐】 震下艮上","description":"周易尚氏学 - 27、【颐】 震下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/032.md","filePath":"zh/classics/shangshi/032.md"}'),s={name:"zh/classics/shangshi/032.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_27、【颐】-震下艮上" tabindex="-1">27、【颐】 震下艮上 <a class="header-anchor" href="#_27、【颐】-震下艮上" aria-label="Permalink to “27、【颐】 震下艮上”">​</a></h1><p>郑玄曰。颐者口车辅也。震动于下。艮止于上。口车动而上。因辅嚼物以养人。故谓之颐。按左传辅车相依注。辅辅颊。车牙车。凡物入口。牙车载之。故曰车。辅在上不动。车在下动而上。故曰因辅嚼物。颐上艮。辅也。不动者也。下震。牙车也。动而上。因辅以嚼物者也。故郑释最得卦义。颐能养人。故贞吉。艮为观为求。震为口。坤为物。故曰口实。实者食也。言口合物以自养也。虞翻谓离为目。郑玄谓二五皆离变故能观。岂知艮一阳在上为光明。为目。为观。象失传。详焦氏易诂不必用卦变及爻位也。</p><p>彖曰。颐贞吉。养正则吉也。观颐。观其所养也。自求口实。现其自养也。天地养万物。圣人养贤以及万民。颐之时大矣哉。</p><p>天地谓初上。坤为万物为民。艮为君子为贤。伏乾为圣人。</p><p>象曰。山下有雷。颐。君子以慎言语。节饮食。</p><p>艮为君子。震为言为食。正反震言语相背。有相讼意。慎则讼息。饮食者人之所欲。震为口。正反艮手相对。有争意。节则饮食平。慎与节皆艮止象。此易用覆象。最为神妙之语。旧说。惟易林能阐其义。说详焦氏易诂。</p><p>初九。舍尔灵龟。观我朵颐。 凶。</p><p>离为龟。以刚在外。艮亦刚在外。故颐。损。益皆以艮为龟。此其义。唯易林知之。屯之震云。龟鳖列市。以震互艮为龟。泰之节云。龟厌河海。以节互艮为龟。虞翻用卦变。以晋离为龟。易取象无此迂曲也。初爻艮覆。故曰舍尔灵龟。朵。释文云动也。人食物则颐动。初应在四。四当颐中。故曰观我朵颐。言初当位。拥有群阴。贞静自养。斯亦足矣。乃舍其自有之灵宝。而阐观他人之宠禄。四艮体艮为贵为官则躁竟贻讥。而殃咎或至。故曰凶。按初当位有应。前临重阴。阳遇阴则通。本无凶理。随初。出门有功。益初。利用为大作。其证也。此则凶者。以艮震相反复。内动外止。故宜静不宜动。屯初云。利居贞。是其义也。屯初至五。亦颐也。由此悟随初有功者。以外兑。兑悦震喜。益初利用为大作者。以外巽。同声相应。故皆动而吉。独屯。初利居贞以外坎。无为险难。故宜贞定。其故全在外卦。颐外艮。又止故不宜动。旧解皆不详凶之故何在。则易理失传。不能观其会通也。</p><h3 id="象曰。观我朵颐。亦不足贵也。" tabindex="-1">象曰。观我朵颐。亦不足贵也。 <a class="header-anchor" href="#象曰。观我朵颐。亦不足贵也。" aria-label="Permalink to “象曰。观我朵颐。亦不足贵也。”">​</a></h3><p>言初本可贵。反因妄动而不足贵也。</p><p>六二。颠颐。拂经。于丘颐。征凶。</p><p>颠与阐（内真）通。和玉藻。盛气颠宝。注颠读为间（内真）。而闻（内真）与穴（下真）通。前汉游侠传。人无贤不肖门（内真）门。注门（内真）与穴（下真）字同。穴（下真）塞也。三四五皆阴。故曰穴（下真）颐。丘前汉息夫躬传。寄宿丘亭。师古云。丘空也。经常。拂违也。丘颐空颐也。盖颐以空为用。今乃穴（下真）塞。违颐之常。故曰穴（下真）颐。拂经于丘颐。前得敌故征凶。其以颠颐拂经为句。或以拂经于丘为句者。非。</p><h3 id="象曰。六二征凶。行失类也。" tabindex="-1">象曰。六二征凶。行失类也。 <a class="header-anchor" href="#象曰。六二征凶。行失类也。" aria-label="Permalink to “象曰。六二征凶。行失类也。”">​</a></h3><p>二无应。前遇重阴。阴遇阴则窒。故曰征凶。阴阳相遇方为类。今六二不遇阳。故曰失类。象义如此明白。乃二千年易家。皆以阴遇阴为类。于是文言之各从其类。坤彖传之乃与类行。系辞之方以类聚。及此皆失解。与朋友同。说详焦氏易诂。</p><p>六三。拂颐。贞凶。十年勿用。无攸利。</p><p>吴先生曰。拂颐犹不可口也。贞占也。坤为十年。三不当位。承乘皆阴。故十年不用。无攸利也。按三有应。阴得阳应多吉。此独不吉者。以四五得敌。应上甚难。故曰无攸利。</p><h3 id="象曰。十年勿用。道大悖也" tabindex="-1">象曰。十年勿用。道大悖也 <a class="header-anchor" href="#象曰。十年勿用。道大悖也" aria-label="Permalink to “象曰。十年勿用。道大悖也”">​</a></h3><p>艮震皆为道路。乃艮震上下象皆相反。故日道大悖。玉篇悖逆也。言艮震皆有覆象相逆也。艮震皆为道。乃上卦覆震。与下震相逆。下卦覆艮。与上艮相逆。象下一悖字。寻味无穷。</p><p>六四。颠颐。吉。虎视眈眈。其欲逐逐。无咎。</p><p>六二无应。以阴穴（下真）颐。故凶。六四有应。穴（下真）颐以阳。故吉。艮为虎为视。眈眈视貌。说文云视近志远。坤为欲。逐逐言所欲在初。乃为二三所阻。不能遽遂其欲。故逐逐不已。</p><h3 id="象曰。颠顾之吉。上施光也。" tabindex="-1">象曰。颠顾之吉。上施光也。 <a class="header-anchor" href="#象曰。颠顾之吉。上施光也。" aria-label="Permalink to “象曰。颠顾之吉。上施光也。”">​</a></h3><p>初阳应四。故曰上施光。三有应不当位。故凶。四当位有应。故吉。然四虽有应。为二三所隔。难以下施。故须初上施而吉也。</p><p>六五。拂经。居贞吉。不可涉大川。</p><p>拂经。王注作拂颐。五不当位。故拂颐。居安也。安居五位。顺上承阳。故贞吉。若下涉坤水。阴遇阴则窒。故不可也。</p><h3 id="象曰。居贞之吉。顺以从上也。" tabindex="-1">象曰。居贞之吉。顺以从上也。 <a class="header-anchor" href="#象曰。居贞之吉。顺以从上也。" aria-label="Permalink to “象曰。居贞之吉。顺以从上也。”">​</a></h3><p>上阳。故当顺从。</p><p>上九。由顾。厉吉。利涉大川。</p><p>由自得也。义详豫九四。九四下乘重阴。故曰由豫。此亦下乘重阴。放曰由颐。然高居万民之上。恐逸豫随之。故振厉方吉也。坤为大川。阳遇阴则通。故利涉大川。此与五爻旧解所以全误者。一由坤水象失传。必用虞翻再三变之法。始得坎为大川。二由类字失诂。故不知和涉不利涉之故何在也。</p><h3 id="象曰。由颐厉吉。大有庆也。" tabindex="-1">象曰。由颐厉吉。大有庆也。 <a class="header-anchor" href="#象曰。由颐厉吉。大有庆也。" aria-label="Permalink to “象曰。由颐厉吉。大有庆也。”">​</a></h3><p>大有庆。谓上九乘重阴。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
